mapper.select:
SELECT a.* FROM ( SELECT @ids AS _ids, ( SELECT @ids := GROUP_CONCAT( id ) FROM BIZ_CAD_FILE WHERE DELETE_FLAG = 'NOT_DELETE' and FIND_IN_SET( PARENT_ID, @ids ) ) AS cids, @l := @l + 1 AS LEVEL FROM BIZ_CAD_FILE, ( SELECT @ids := ${fileId}, @l := 0 ) b WHERE @ids IS NOT NULL ) b, BIZ_CAD_FILE a WHERE FIND_IN_SET( a.id, b._ids )
and a.`TYPE` = #{type}
ORDER BY LEVEL, id
